ee:variables.ee:set-variable:
%dw 2.0
output application/java
var desc = error.description default ""
---
if ((desc contains "Duplicate entry") and (desc contains "idempotency_keys"))
  { status: 409, code: "IDEMPOTENCY_KEY_IN_PROGRESS", message: "A request with this Idempotency-Key is still being processed. Please retry shortly." }
else if ((desc contains "Duplicate entry") and (desc contains "customer_users.email"))
  { status: 409, code: "DUPLICATE_EMAIL", message: "An account already exists for this email. Please sign in or reset your password." }
else
  { status: 500, code: "SYSTEM_ERROR", message: "We could not complete your registration. Please try again later." }

db:insert.db:input-parameters:
#[{
  tokenHash: vars.resend.tokenHash,
  customerId: vars.custRow[0].customer_id,
  email: vars.resendEmailAddress
}]
